SELECT 'core-2026-09-v4','conditionals','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"conditionals","title":"Zero, first and second conditionals","level":"B1","order":42,"summary":"Express regular consequences, realistic future possibilities and imagined alternatives.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["General conditions","A realistic future possibility","An imagined present or future","Clause order and unless"],"rules":[{"title":"General conditions","explanation":"A common **zero conditional** uses present simple in both clauses for a regular consequence or general relationship. If can sometimes be replaced by when when the event is expected or repeated. It is the general meaning, not only the verb forms, that matters.","pattern":"If water freezes, it **expands**.","commonMistakes":["A conditional can also contain an instruction: If you need help, ask. Not every if sentence belongs to one numbered formula."],"examples":["State a regular procedure in the zero conditional: “Whenever an order arrives, she **prepares** the visitor guide.”","State a regular procedure in the zero conditional: “Whenever an order arrives, she **restores** the old portrait.”"],"skill":"form"},{"title":"A realistic future possibility","explanation":"The usual **first conditional** has if + present simple, followed by will + base verb. It treats the condition as a realistic possibility. The result can also use can, may or an imperative when that meaning is appropriate.","pattern":"If she **calls**, I **will answer**.","commonMistakes":["In an ordinary future condition, do not put will in the if clause. Will can occur there with other meanings, such as willingness."],"examples":["Use the standard first conditional: “If she **prepares** the visitor guide tomorrow, we will be ready.”","Use the standard first conditional: “If she **restores** the old portrait tomorrow, we will be ready.”"],"skill":"meaning"},{"title":"An imagined present or future","explanation":"A common **second conditional** uses if + past simple with would + base verb. The past form marks distance from reality rather than necessarily past time. Were is common for all subjects in formal hypothetical be clauses, especially If I were you.","pattern":"If I **had** time, I **would visit**.","commonMistakes":["The form does not mean the imagined event happened in the past; it often concerns now or the future."],"examples":["Use the second conditional for an imagined situation now: “If she **prepared** the visitor guide, we would have less work.”","Use the second conditional for an imagined situation now: “If she **restored** the old portrait, we would have less work.”"],"skill":"contrast"},{"title":"Clause order and unless","explanation":"The clauses can swap order without changing the basic relationship. A leading if clause is normally followed by a comma. Unless often means if not, but replacing every negative condition mechanically can change meaning.","pattern":"If it rains, we’ll stay. / We’ll stay if it rains.","commonMistakes":["Do not add a second negative merely because unless already has an if-not meaning."],"examples":["Complete the second-conditional result: “If I had more time now, I **would prepare** the visitor guide.”","Complete the second-conditional result: “If I had more time now, I **would restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Express regular consequences, realistic future possibilities and imagined alternatives.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"General conditions","explanation":"A common **zero conditional** uses present simple in both clauses for a regular consequence or general relationship. If can sometimes be replaced by when when the event is expected or repeated. It is the general meaning, not only the verb forms, that matters.","pattern":"If water freezes, it **expands**.","commonMistakes":["A conditional can also contain an instruction: If you need help, ask. Not every if sentence belongs to one numbered formula."],"examples":["State a regular procedure in the zero conditional: “Whenever an order arrives, she **prepares** the visitor guide.”","State a regular procedure in the zero conditional: “Whenever an order arrives, she **restores** the old portrait.”"],"skill":"form","id":"conditionals-foundation-1","domain":"adjuncts","referenceIds":["bc-conditionals"],"readingVersion":"core-2026-09-v3"},{"title":"A realistic future possibility","explanation":"The usual **first conditional** has if + present simple, followed by will + base verb. It treats the condition as a realistic possibility. The result can also use can, may or an imperative when that meaning is appropriate.","pattern":"If she **calls**, I **will answer**.","commonMistakes":["In an ordinary future condition, do not put will in the if clause. Will can occur there with other meanings, such as willingness."],"examples":["Use the standard first conditional: “If she **prepares** the visitor guide tomorrow, we will be ready.”","Use the standard first conditional: “If she **restores** the old portrait tomorrow, we will be ready.”"],"skill":"meaning","id":"conditionals-foundation-2","domain":"adjuncts","referenceIds":["bc-conditionals"],"readingVersion":"core-2026-09-v3"},{"title":"An imagined present or future","explanation":"A common **second conditional** uses if + past simple with would + base verb. The past form marks distance from reality rather than necessarily past time. Were is common for all subjects in formal hypothetical be clauses, especially If I were you.","pattern":"If I **had** time, I **would visit**.","commonMistakes":["The form does not mean the imagined event happened in the past; it often concerns now or the future."],"examples":["Use the second conditional for an imagined situation now: “If she **prepared** the visitor guide, we would have less work.”","Use the second conditional for an imagined situation now: “If she **restored** the old portrait, we would have less work.”"],"skill":"contrast","id":"conditionals-foundation-3","domain":"adjuncts","referenceIds":["bc-conditionals"],"readingVersion":"core-2026-09-v3"},{"title":"Clause order and unless","explanation":"The clauses can swap order without changing the basic relationship. A leading if clause is normally followed by a comma. Unless often means if not, but replacing every negative condition mechanically can change meaning.","pattern":"If it rains, we’ll stay. / We’ll stay if it rains.","commonMistakes":["Do not add a second negative merely because unless already has an if-not meaning."],"examples":["Complete the second-conditional result: “If I had more time now, I **would prepare** the visitor guide.”","Complete the second-conditional result: “If I had more time now, I **would restore** the old portrait.”"],"skill":"application","id":"conditionals-foundation-4","domain":"adjuncts","referenceIds":["bc-conditionals"],"readingVersion":"core-2026-09-v3"}],"recap":["If water freezes, it **expands**.","If she **calls**, I **will answer**.","If I **had** time, I **would visit**.","If it rains, we’ll stay. / We’ll stay if it rains."],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["past-modals"],"readingReferenceIds":["bc-conditionals"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='conditionals'
